import json
from pathlib import Path
p=Path('PCB');n=json.loads((p/'reports/full-schematic-v06.net').read_text());cs={c['props']['Designator']:c for c in n['components'].values()};plan=json.loads((p/'manifests/revision-v06.json').read_text());base='if((await eda.dmt_Project.getCurrentProjectInfo())?.uuid!=="'+n['projectId']+'")throw Error("Wrong project");await eda.dmt_EditorControl.openDocument("4211128ecf040c100b33238447713203");'
a=cs['U8']['props'];core=['Unique ID','Designator','Name','Manufacturer','Manufacturer Part','Supplier','Supplier Part','Add into BOM','Convert to PCB','Device','Footprint','PCB Layer','Symbol'];props={'designator':'U8','uniqueId':a['Unique ID'],'name':a.get('Name',''),'manufacturer':a.get('Manufacturer',''),'manufacturerId':a.get('Manufacturer Part',''),'supplier':a.get('Supplier',''),'supplierId':a.get('Supplier Part',''),'addIntoBom':True,'otherProperty':{k:v for k,v in a.items() if k not in core}}
code=base+'const refs='+json.dumps(plan['removedThisRevision']+['U8'])+';for(const c of await eda.pcb_PrimitiveComponent.getAll())if(refs.includes(c.getState_Designator()))if(!await eda.pcb_PrimitiveComponent.delete(c))throw Error("Delete failed");const stale=["Q5_BASE","Q6_BASE","485_DE_GATED"];for(const q of await eda.pcb_PrimitiveLine.getAll())if(stale.includes(q.getState_Net()))await eda.pcb_PrimitiveLine.delete(q);for(const q of await eda.pcb_PrimitiveVia.getAll())if(stale.includes(q.getState_Net()))await eda.pcb_PrimitiveVia.delete(q);for(const q of await eda.pcb_PrimitivePolyline.getAll())if(stale.includes(q.getState_Net()))await eda.pcb_PrimitivePolyline.delete(q);const c=await eda.pcb_PrimitiveComponent.create('+json.dumps({'libraryUuid':n['projectId'],'uuid':a['Device']})+',1,2800,100,0,false);if(!c)throw Error("Create failed");await eda.pcb_PrimitiveComponent.modify(c,'+json.dumps(props)+');const map='+json.dumps({r:plan['expected'][r] for r in ['U8','U6','R121','R37','U14','R32']})+';for(const c of await eda.pcb_PrimitiveComponent.getAll()){const r=c.getState_Designator();if(!map[r])continue;if(r==="R32")await eda.pcb_PrimitiveComponent.modify(c,{addIntoBom:false});for(const pin of await eda.pcb_PrimitiveComponent.getAllPinsByPrimitiveId(c.getState_PrimitiveId())){const z=pin.toAsync();z.setState_Net(map[r][pin.getState_PadNumber()]||"");await z.done();}}return {saved:await eda.pcb_Document.save(),remaining:(await eda.pcb_PrimitiveComponent.getAll()).length};'
(p/'scripts/sync-pcb-v06.js').write_text(code,encoding='utf-8')
